<?php $nextSort=$items?min(999999,max(array_column($items,'sort_order'))+10):10; ?>
<section class="panel admin-form"><h2><?= $record?'编辑友情链接':'新增友情链接' ?></h2><form method="post" class="stack-form">
 <?= csrfField() ?><input type="hidden" name="id" value="<?= (int)$v('id',0) ?>">
 <div class="form-grid"><label>网站名称<input name="label" value="<?= e($v('label')) ?>" maxlength="40" required placeholder="填写合作网站名称"></label><label>排序<input type="number" name="sort_order" value="<?= (int)$v('sort_order',$nextSort) ?>" min="0" max="999999" required><small class="field-help">数字越小越靠前，也可使用下方的上移、下移。</small></label></div>
 <label>网站地址<input type="url" name="url" value="<?= e($v('url')) ?>" maxlength="1000" placeholder="https://example.com/" required></label>
 <div class="form-grid"><label>显示状态<select name="enabled"><option value="1" <?= $v('enabled',1)==1?'selected':'' ?>>显示</option><option value="0" <?= $v('enabled',1)==0?'selected':'' ?>>隐藏</option></select></label><label>打开方式<select name="new_tab"><option value="1" <?= $v('new_tab',1)==1?'selected':'' ?>>新窗口</option><option value="0" <?= $v('new_tab',1)==0?'selected':'' ?>>当前窗口</option></select></label></div>
 <div class="form-actions"><button class="button">保存友情链接</button><?php if($record): ?><a href="<?= e(adminUrl('friendlinks')) ?>" class="text-link">取消编辑</a><?php endif ?></div>
 </form></section>
<section class="panel navigation-panel friend-links-panel"><div class="section-heading"><h2>友情链接 <small><?= count($items) ?> 项</small></h2><a href="/" target="_blank" rel="noopener" class="accent-link">查看网站页脚</a></div><p class="field-help">已显示的友情链接按顺序出现在前台页脚。隐藏的链接仅在后台保留。</p><div class="navigation-list">
 <?php foreach($items as $index=>$item): ?><article class="navigation-row" data-friend-link-id="<?= (int)$item['id'] ?>"><span class="navigation-rank"><?= $index+1 ?></span><div class="navigation-description"><h3><?= e($item['label']) ?> <span class="navigation-status <?= $item['enabled']?'':'is-hidden' ?>"><?= $item['enabled']?'显示':'隐藏' ?></span></h3><a href="<?= e($item['url']) ?>" target="_blank" rel="noopener" class="navigation-url"><?= e($item['url']) ?></a><small>排序 <?= (int)$item['sort_order'] ?> · <?= $item['new_tab']?'新窗口':'当前窗口' ?></small></div><div class="navigation-actions"><a class="button button-outline small" href="<?= e(adminUrl('friendlinks',['edit'=>$item['id']])) ?>">编辑</a><?php foreach(['up'=>'上移','down'=>'下移','toggle'=>$item['enabled']?'隐藏':'显示','delete'=>'删除'] as $action=>$label): ?><form method="post"<?= $action==='delete'?' data-confirm="确定删除这条友情链接？"':'' ?>><?= csrfField() ?><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><input type="hidden" name="action" value="<?= e($action) ?>"><button class="text-button <?= $action==='delete'?'danger':'' ?>"<?= ($action==='up'&&$index===0)||($action==='down'&&$index===count($items)-1)?' disabled':'' ?>><?= e($label) ?></button></form><?php endforeach ?></div></article><?php endforeach ?>
 <?php if(!$items): ?><div class="empty-state">暂无友情链接，请在上方新增。</div><?php endif ?></div></section>
